    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    queries = list(map(int, data[1:]))

    # Precompute the minimum number of rolls needed for each target from 2 to 100
    min_rolls = [float('inf')] * 101
    dice_faces = [2, 3, 4, 5, 6, 7]

    for i in range(2, 101):
        for face in dice_faces:
            if i >= face:
                min_rolls[i] = min(min_rolls[i], min_rolls[i - face] + 1)
            else:
                break

    results = []
    for x in queries:
        results.append(min_rolls[x])

